#ifdef TEST_UNSPLIT_FLATEN_DV
// unsplit, part 5 of 8 -- `flaten`, the shock-flattening coefficient.
//
// Output is in [0,1] per cell: 1 where the flow is smooth, falling toward 0
// only where BOTH a large relative pressure jump AND a COMPRESSIVE velocity
// field are present.  `slope` multiplies its slopes by it, so near a shock the
// reconstruction drops back toward first order.
//
// The oracle is what a flattener IS, not this arithmetic: smooth -> exactly 1;
// godorder /= 2 -> exactly 0; a compressive shock -> 0 at the shock; the SAME
// pressure profile with an EXPANDING velocity -> 1 (the velocity test is what
// tells a shock from a rarefaction, and the pair differs in nothing else);
// always within [0,1]; and an x-only shock leaves the y pass at 1, so a
// transposed subscript shows up.
namespace ufl {
  const int NCX = 4;
  struct W {
    int nc1, nc2, W_, H_;
    std::vector<double> a;
    W (int c1, int c2, double fill)
        : nc1 (c1), nc2 (c2), W_ (c1 + 2 * NCX), H_ (c2 + 2 * NCX),
          a ((size_t)W_ * H_, fill) {}
    double &at (int j, int i) { return a[(size_t)(j - (1 - NCX)) * W_ + (i - (1 - NCX))]; }
    double at (int j, int i) const { return a[(size_t)(j - (1 - NCX)) * W_ + (i - (1 - NCX))]; }
    sisal_array_t dope () const {
      sisal_array_t d = sisal_array_alloc_sized (2, 4, (uint64_t)a.size (), sizeof (double));
      d.dims[0] = H_; d.dims[1] = W_;
      d.lower_bound[0] = 1 - NCX; d.lower_bound[1] = 1 - NCX;
      memcpy (d.data, a.data (), a.size () * sizeof (double));
      return d;
    }
  };
  // the formula, transcribed
  static void ref (const W &p, const W &u, const W &v, int god,
                   std::vector<double> &out)
  {
    const int nc1 = p.nc1, nc2 = p.nc2, rw = nc1 + 2;
    const double small = 1e-6, shk = 0.33, z1 = 0.75, dz = 1.0 / (0.85 - 0.75);
    out.assign ((size_t)rw * (nc2 + 2), 0.0);
    if (god != 2) return;
    auto chi = [&] (double dp, double den, double lo, bool comp) {
      double zeta = fabs (dp) / std::max (small, den);
      double z = std::min (1.0, std::max (0.0, dz * (zeta - z1)));
      double c = ((fabs (dp) / lo) > shk) ? (comp ? 1.0 : 0.0) : 0.0;
      return c * z;
    };
    for (int j = 0; j <= nc2 + 1; j++)
      for (int i = 0; i <= nc1 + 1; i++)
        {
          double mx = 0;
          for (int k = i - 1; k <= i + 1; k++)
            mx = std::max (mx, chi (p.at (j, k + 1) - p.at (j, k - 1),
                                    fabs (p.at (j, k + 2) - p.at (j, k - 2)),
                                    std::min (p.at (j, k + 1), p.at (j, k - 1)),
                                    u.at (j, k - 1) >= u.at (j, k + 1)));
          double fx = 1.0 - mx;
          double my = 0;
          for (int k = j - 1; k <= j + 1; k++)
            my = std::max (my, chi (p.at (k + 1, i) - p.at (k - 1, i),
                                    fabs (p.at (k + 2, i) - p.at (k - 2, i)),
                                    std::min (p.at (k + 1, i), p.at (k - 1, i)),
                                    v.at (k - 1, i) >= v.at (k + 1, i)));
          double fy = 1.0 - my;
          out[(size_t)j * rw + i] = std::min (fx, fy);
        }
  }
}
static void test_unsplit_flaten_dv (void)
{
  printf ("\n=== Group: unsplit_flaten_dv (part 5/8: shock flattening) ===\n");
  using namespace ufl;
  const int nc1 = 7, nc2 = 6, rw = nc1 + 2;

  auto run = [&] (const W &p, const W &u, const W &v, int god,
                  std::vector<double> &out) {
    sisal_array_t pp = p.dope (), uu = u.dope (), vv = v.dope ();
    sisal_array_t r = func_MAIN (pp, uu, vv, nc1, nc2, god);
    bool shape = r.rank == 2 && (int)r.dims[0] == nc2 + 2
                 && (int)r.dims[1] == nc1 + 2;
    out.assign ((size_t)rw * (nc2 + 2), -99.0);
    if (shape)
      memcpy (out.data (), r.data, out.size () * sizeof (double));
    if (pp.data) free (pp.data);
    if (uu.data) free (uu.data);
    if (vv.data) free (vv.data);
    if (r.data) free (r.data);
    return shape;
  };

  // ---- smooth flow: nothing to flatten ----
  {
    W p (nc1, nc2, 1.0), u (nc1, nc2, 0.0), v (nc1, nc2, 0.0);
    for (int j = 1 - NCX; j <= nc2 + NCX; j++)
      for (int i = 1 - NCX; i <= nc1 + NCX; i++)
        p.at (j, i) = 1.0 + 0.01 * i;          // gentle gradient
    std::vector<double> f;
    bool ok = run (p, u, v, 2, f);
    for (size_t k = 0; ok && k < f.size (); k++) if (f[k] != 1.0) ok = false;
    check ("smooth flow: coefficient is exactly 1 everywhere", ok);
  }

  // ---- godorder /= 2: identically zero ----
  {
    W p (nc1, nc2, 1.0), u (nc1, nc2, 0.0), v (nc1, nc2, 0.0);
    for (int j = 1 - NCX; j <= nc2 + NCX; j++)
      for (int i = 1 - NCX; i <= nc1 + NCX; i++)
        { p.at (j, i) = (i <= 3) ? 10.0 : 1.0; u.at (j, i) = (i <= 3) ? 5.0 : -5.0; }
    std::vector<double> f;
    bool ok = run (p, u, v, 1, f);
    for (size_t k = 0; ok && k < f.size (); k++) if (f[k] != 0.0) ok = false;
    check ("godorder /= 2: coefficient is identically zero", ok);
  }

  // ---- a compressive shock flattens; the same jump expanding does not ----
  {
    W p (nc1, nc2, 1.0), uc (nc1, nc2, 0.0), ue (nc1, nc2, 0.0),
        v (nc1, nc2, 0.0);
    for (int j = 1 - NCX; j <= nc2 + NCX; j++)
      for (int i = 1 - NCX; i <= nc1 + NCX; i++)
        {
          p.at (j, i) = (i <= 3) ? 10.0 : 1.0;   // strong jump at i = 3/4
          uc.at (j, i) = (i <= 3) ? 5.0 : -5.0;  // converging  -> compressive
          ue.at (j, i) = (i <= 3) ? -5.0 : 5.0;  // diverging   -> expansion
        }
    std::vector<double> fc, fe;
    bool ok = run (p, uc, v, 2, fc) && run (p, ue, v, 2, fe);

    double lo = 2.0;
    for (size_t k = 0; k < fc.size (); k++) lo = std::min (lo, fc[k]);
    check ("compressive shock drives the coefficient to 0 somewhere",
           ok && lo == 0.0);

    bool allone = true;
    for (size_t k = 0; k < fe.size (); k++) if (fe[k] != 1.0) allone = false;
    check ("the SAME pressure jump, expanding, leaves it at 1 (shock vs "
           "rarefaction)", ok && allone);

    bool range = true;
    for (size_t k = 0; k < fc.size (); k++)
      if (!(fc[k] >= 0.0 && fc[k] <= 1.0)) range = false;
    check ("coefficient stays within [0,1]", range);
  }

  // ---- direction separation: an x-only shock is found by the x pass ----
  {
    W px (nc1, nc2, 1.0), py (nc1, nc2, 1.0), u (nc1, nc2, 0.0),
        v (nc1, nc2, 0.0), uc (nc1, nc2, 0.0), vc (nc1, nc2, 0.0);
    for (int j = 1 - NCX; j <= nc2 + NCX; j++)
      for (int i = 1 - NCX; i <= nc1 + NCX; i++)
        {
          px.at (j, i) = (i <= 3) ? 10.0 : 1.0;
          py.at (j, i) = (j <= 3) ? 10.0 : 1.0;
          uc.at (j, i) = (i <= 3) ? 5.0 : -5.0;
          vc.at (j, i) = (j <= 3) ? 5.0 : -5.0;
        }
    std::vector<double> fx, fy;
    bool ok = run (px, uc, v, 2, fx) && run (py, u, vc, 2, fy);
    // x-shock: rows all identical (the y pass sees nothing)
    bool rows_same = ok;
    for (int j = 1; rows_same && j <= nc2 + 1; j++)
      for (int i = 0; i <= nc1 + 1; i++)
        if (fx[(size_t)j * rw + i] != fx[(size_t)0 * rw + i]) rows_same = false;
    check ("x-only shock: every row of the coefficient is identical", rows_same);
    // y-shock: columns all identical
    bool cols_same = ok;
    for (int j = 0; cols_same && j <= nc2 + 1; j++)
      for (int i = 1; i <= nc1 + 1; i++)
        if (fy[(size_t)j * rw + i] != fy[(size_t)j * rw + 0]) cols_same = false;
    check ("y-only shock: every column of the coefficient is identical",
           cols_same);
    // and the two are transposes of one another on a square patch
    check ("x-shock and y-shock answers are non-trivial (some cell flattened)",
           ok && *std::min_element (fx.begin (), fx.end ()) < 1.0
               && *std::min_element (fy.begin (), fy.end ()) < 1.0);
  }

  // ---- transcription, on non-symmetric data ----
  {
    W p (nc1, nc2, 1.0), u (nc1, nc2, 0.0), v (nc1, nc2, 0.0);
    for (int j = 1 - NCX; j <= nc2 + NCX; j++)
      for (int i = 1 - NCX; i <= nc1 + NCX; i++)
        {
          p.at (j, i) = 1.0 + 4.0 * (i >= 2 && i <= 5 ? 1.0 : 0.0)
                        + 0.5 * (j >= 3 ? 1.0 : 0.0) + 0.03 * i * j;
          // V-shaped, so u[k-1] >= u[k+1] is true on one side and false on the
          // other -- a monotone u would make the compressive test fire
          // everywhere and stop this dataset from discriminating on it
          u.at (j, i) = fabs ((double)(i - 4)) - 0.3 * j;
          v.at (j, i) = fabs ((double)(j - 3)) - 0.2 * i;
        }
    std::vector<double> got, want;
    bool ok = run (p, u, v, 2, got);
    ref (p, u, v, 2, want);
    for (size_t k = 0; ok && k < got.size (); k++)
      if (fabs (got[k] - want[k]) > 1e-12) ok = false;
    check ("non-symmetric flow matches the transcribed formula", ok);
  }
}
#endif
#ifdef TEST_UNSPLIT_SLOPE_DV
// unsplit, part 4 of 8 -- `slope`, the limited-slope reconstruction.
//
// The oracle is the limiter's DEFINING PROPERTIES, which hold whatever the
// arithmetic looks like: linear data reconstructs its slope EXACTLY, a local
// extremum zeroes the slope, constant data gives zero, the result is linear in
// flatn, and data varying along one axis only must give zero slope on the
// other (which is what catches a transposed subscript).  A straight
// transcription of the formula runs alongside on non-symmetric data, to catch
// a mis-ported index the properties might not disturb.
//
// Index span: q is read at [j, i+-2] over i in -1..nc1+2, so -3 .. nc1+4 --
// exactly what PhysBnd produces with ncx = 4 (part 3).  The parts line up by
// construction.
namespace usl {
  const int NCX = 4;
  // wide plane: index (j,i) over 1-NCX .. n+NCX, stored row-major
  struct W {
    int nc1, nc2, W_, H_;
    std::vector<double> a;
    W (int c1, int c2) : nc1 (c1), nc2 (c2), W_ (c1 + 2 * NCX),
                         H_ (c2 + 2 * NCX), a ((size_t)W_ * H_, 0.0) {}
    double &at (int j, int i) {
      return a[(size_t)(j - (1 - NCX)) * W_ + (i - (1 - NCX))];
    }
    double at (int j, int i) const {
      return a[(size_t)(j - (1 - NCX)) * W_ + (i - (1 - NCX))];
    }
    sisal_array_t dope () const {
      sisal_array_t d = sisal_array_alloc_sized (2, 4, (uint64_t)a.size (),
                                                 sizeof (double));
      d.dims[0] = H_; d.dims[1] = W_;
      d.lower_bound[0] = 1 - NCX; d.lower_bound[1] = 1 - NCX;
      memcpy (d.data, a.data (), a.size () * sizeof (double));
      return d;
    }
  };
  static double sgn (double y) { return y >= 0.0 ? 1.0 : -1.0; }
  // the formula, transcribed
  static void ref_slope (const W &q, const W &fl, std::vector<double> &dx,
                         std::vector<double> &dy)
  {
    const int nc1 = q.nc1, nc2 = q.nc2;
    const int rw = nc1 + 2, rh = nc2 + 2;          // result spans 0..n+1
    dx.assign ((size_t)rw * rh, 0.0);
    dy.assign ((size_t)rw * rh, 0.0);
    const double t3 = 2.0 / 3.0, s6 = 1.0 / 6.0;
    for (int j = 0; j <= nc2 + 1; j++)
      {
        std::vector<double> df (nc1 + 6), ds (nc1 + 6), dl (nc1 + 6);
        auto ix = [&] (int i) { return i + 2; };   // i runs -1 .. nc1+2
        for (int i = -1; i <= nc1 + 2; i++)
          {
            double dcen = 0.5 * (q.at (j, i + 1) - q.at (j, i - 1));
            double dlft = 2.0 * (q.at (j, i) - q.at (j, i - 1));
            double drgt = 2.0 * (q.at (j, i + 1) - q.at (j, i));
            double slop = std::min (fabs (dlft), std::min (fabs (drgt), fabs (dcen)));
            double lim = (dlft * drgt >= 0.0) ? slop : 0.0;
            ds[ix (i)] = sgn (dcen); dl[ix (i)] = lim;
            df[ix (i)] = sgn (dcen) * lim;
          }
        for (int i = 0; i <= nc1 + 1; i++)
          {
            double d3 = t3 * (q.at (j, i + 1) - q.at (j, i - 1))
                        - s6 * (df[ix (i + 1)] - df[ix (i - 1)]);
            dx[(size_t)j * rw + i] = fl.at (j, i) * ds[ix (i)]
                                     * std::min (dl[ix (i)], fabs (d3));
          }
      }
    // y direction
    std::vector<double> Xdf ((size_t)(nc2 + 6) * (nc1 + 2)),
        Xds ((size_t)(nc2 + 6) * (nc1 + 2)), Xdl ((size_t)(nc2 + 6) * (nc1 + 2));
    auto jx = [&] (int j, int i) { return (size_t)(j + 2) * (nc1 + 2) + i; };
    for (int j = -1; j <= nc2 + 2; j++)
      for (int i = 0; i <= nc1 + 1; i++)
        {
          double dcen = 0.5 * (q.at (j + 1, i) - q.at (j - 1, i));
          double dlft = 2.0 * (q.at (j, i) - q.at (j - 1, i));
          double drgt = 2.0 * (q.at (j + 1, i) - q.at (j, i));
          double slop = std::min (fabs (dlft), std::min (fabs (drgt), fabs (dcen)));
          double lim = (dlft * drgt >= 0.0) ? slop : 0.0;
          Xds[jx (j, i)] = sgn (dcen); Xdl[jx (j, i)] = lim;
          Xdf[jx (j, i)] = sgn (dcen) * lim;
        }
    for (int j = 0; j <= nc2 + 1; j++)
      for (int i = 0; i <= nc1 + 1; i++)
        {
          double d4 = t3 * (q.at (j + 1, i) - q.at (j - 1, i))
                      - s6 * (Xdf[jx (j + 1, i)] - Xdf[jx (j - 1, i)]);
          dy[(size_t)j * rw + i] = fl.at (j, i) * Xds[jx (j, i)]
                                   * std::min (Xdl[jx (j, i)], fabs (d4));
        }
  }
}
static void test_unsplit_slope_dv (void)
{
  printf ("\n=== Group: unsplit_slope_dv (part 4/8: the limiter) ===\n");
  using namespace usl;
  const int nc1 = 6, nc2 = 5;
  const int rw = nc1 + 2;
  char msg[190];

  auto run = [&] (const W &q, const W &fl, std::vector<double> &dx,
                  std::vector<double> &dy) {
    sisal_array_t qq = q.dope (), ff = fl.dope ();
    sisal_array_t r = func_MAIN (qq, ff, nc1, nc2);
    bool shape = r.rank == 3 && (int)r.dims[0] == 2
                 && (int)r.dims[1] == nc2 + 2 && (int)r.dims[2] == nc1 + 2;
    dx.assign ((size_t)rw * (nc2 + 2), 0.0);
    dy.assign ((size_t)rw * (nc2 + 2), 0.0);
    if (shape)
      {
        const double *p = (const double *)r.data;
        size_t plane = (size_t)(nc2 + 2) * rw;
        for (size_t k = 0; k < plane; k++) { dx[k] = p[k]; dy[k] = p[plane + k]; }
      }
    if (qq.data) free (qq.data);
    if (ff.data) free (ff.data);
    if (r.data) free (r.data);
    return shape;
  };

  W ones (nc1, nc2);
  for (auto &v : ones.a) v = 1.0;

  // ---- linear data reconstructs its slope EXACTLY ----
  {
    const double b = 0.375;                 // exact in binary
    W q (nc1, nc2);
    for (int j = 1 - NCX; j <= nc2 + NCX; j++)
      for (int i = 1 - NCX; i <= nc1 + NCX; i++) q.at (j, i) = 2.0 + b * i;
    std::vector<double> dx, dy;
    bool ok = run (q, ones, dx, dy);
    for (int j = 0; ok && j <= nc2 + 1; j++)
      for (int i = 0; i <= nc1 + 1; i++)
        if (dx[(size_t)j * rw + i] != b || dy[(size_t)j * rw + i] != 0.0)
          { ok = false; break; }
    check ("linear in i: x-slope is exactly b, y-slope exactly 0", ok);
  }
  {
    const double b = -0.25;
    W q (nc1, nc2);
    for (int j = 1 - NCX; j <= nc2 + NCX; j++)
      for (int i = 1 - NCX; i <= nc1 + NCX; i++) q.at (j, i) = 7.0 + b * j;
    std::vector<double> dx, dy;
    bool ok = run (q, ones, dx, dy);
    for (int j = 0; ok && j <= nc2 + 1; j++)
      for (int i = 0; i <= nc1 + 1; i++)
        if (dy[(size_t)j * rw + i] != b || dx[(size_t)j * rw + i] != 0.0)
          { ok = false; break; }
    check ("linear in j: y-slope is exactly b, x-slope exactly 0", ok);
  }

  // ---- constant data gives zero everywhere ----
  {
    W q (nc1, nc2);
    for (auto &v : q.a) v = 3.5;
    std::vector<double> dx, dy;
    bool ok = run (q, ones, dx, dy);
    for (size_t k = 0; ok && k < dx.size (); k++)
      if (dx[k] != 0.0 || dy[k] != 0.0) ok = false;
    check ("constant data gives zero slope in both directions", ok);
  }

  // ---- a local extremum is clipped to zero ----
  {
    // A TENT: q rises to a peak at i = 3 and falls after.  At the peak the left
    // and right differences disagree in sign, so the slope is clipped; on the
    // ramps they agree and the slope survives.  (A single-cell SPIKE on a
    // constant field would clip the whole row instead -- its neighbours have
    // dlft or drgt exactly 0, and the limiter takes the smallest magnitude --
    // which is correct but shows nothing about the ramp, so it is checked
    // separately below.)
    W q (nc1, nc2);
    for (int j = 1 - NCX; j <= nc2 + NCX; j++)
      for (int i = 1 - NCX; i <= nc1 + NCX; i++)
        q.at (j, i) = (double)(i <= 3 ? i : 6 - i);
    std::vector<double> dx, dy;
    bool ok = run (q, ones, dx, dy);
    for (int j = 0; ok && j <= nc2 + 1; j++)
      if (dx[(size_t)j * rw + 3] != 0.0) ok = false;
    check ("tent: the peak cell has its slope clipped to zero", ok);
    bool ramp = true;
    for (int j = 0; ramp && j <= nc2 + 1; j++)
      for (int i : { 1, 2 })
        if (dx[(size_t)j * rw + i] == 0.0) ramp = false;
    check ("tent: cells on the ramp keep a non-zero slope", ramp);
  }

  // ---- an isolated spike clips its neighbours too, by the min ----
  {
    W q (nc1, nc2);
    for (int j = 1 - NCX; j <= nc2 + NCX; j++)
      for (int i = 1 - NCX; i <= nc1 + NCX; i++)
        q.at (j, i) = (i == 3) ? 10.0 : 1.0;
    std::vector<double> dx, dy;
    bool ok = run (q, ones, dx, dy);
    for (size_t k = 0; ok && k < dx.size (); k++)
      if (dx[k] != 0.0) ok = false;
    check ("isolated spike on a flat field: every x-slope is zero (min picks "
           "the flat side)", ok);
  }

  // ---- linear in flatn ----
  {
    const double b = 0.5;
    W q (nc1, nc2);
    for (int j = 1 - NCX; j <= nc2 + NCX; j++)
      for (int i = 1 - NCX; i <= nc1 + NCX; i++) q.at (j, i) = b * i;
    W half (nc1, nc2), zero (nc1, nc2);
    for (auto &v : half.a) v = 0.5;
    std::vector<double> d1x, d1y, dhx, dhy, dzx, dzy;
    run (q, ones, d1x, d1y); run (q, half, dhx, dhy); run (q, zero, dzx, dzy);
    bool ok = true;
    for (size_t k = 0; ok && k < d1x.size (); k++)
      ok = dhx[k] == 0.5 * d1x[k] && dzx[k] == 0.0;
    check ("the slope is linear in flatn (half halves it, zero kills it)", ok);
  }

  // ---- and the transcribed formula, on non-symmetric data ----
  {
    W q (nc1, nc2), fl (nc1, nc2);
    for (int j = 1 - NCX; j <= nc2 + NCX; j++)
      for (int i = 1 - NCX; i <= nc1 + NCX; i++)
        {
          q.at (j, i) = 0.125 * i * i - 0.25 * j + 0.5 * i * j;
          fl.at (j, i) = 0.75;
        }
    std::vector<double> dx, dy, wx, wy;
    bool ok = run (q, fl, dx, dy);
    ref_slope (q, fl, wx, wy);
    for (size_t k = 0; ok && k < dx.size (); k++)
      if (fabs (dx[k] - wx[k]) > 1e-12 || fabs (dy[k] - wy[k]) > 1e-12)
        ok = false;
    check ("non-symmetric data matches the transcribed formula, both planes",
           ok);
  }

  snprintf (msg, sizeof msg, "result is rank 3, (2, %d, %d)", nc2 + 2, nc1 + 2);
  {
    W q (nc1, nc2);
    for (auto &v : q.a) v = 1.0;
    sisal_array_t qq = q.dope (), ff = ones.dope ();
    sisal_array_t r = func_MAIN (qq, ff, nc1, nc2);
    check (msg, r.rank == 3 && (int)r.dims[0] == 2
                    && (int)r.dims[1] == nc2 + 2 && (int)r.dims[2] == nc1 + 2);
    if (qq.data) free (qq.data);
    if (ff.data) free (ff.data);
    if (r.data) free (r.data);
  }
}
#endif
#ifdef TEST_UNSPLIT_BND_DV
// unsplit, part 3 of 7 -- PhysBnd: surround the nx x ny interior with ncx = 4
// ghost cells, filled by WRAPPING (periodic) or CLAMPING to the edge cell, per
// axis independently.
//
// The oracle needs no arithmetic: every output cell is a COPY of some interior
// cell, and which one is fixed by the wrap/clamp rule
//
//     j <= 0  -> yperiod ? ny+j : 1        i <= 0  -> xperiod ? nx+i : 1
//     j >  ny -> yperiod ? j-ny : ny       i >  nx -> xperiod ? i-nx : nx
//
// so the interior is filled with distinct values and every one of the
// (ny+8) x (nx+8) cells is checked against the cell the rule names.  Corners
// are covered by construction, since both rules apply there at once.
//
// The result is indexed 1-ncx .. ny+ncx by 1-ncx .. nx+ncx -- gathers preserve
// their generator's origin and `||` keeps the left operand's -- so the buffer
// offset of (j,i) is (j-(1-ncx))*(nx+2ncx) + (i-(1-ncx)).
static void test_unsplit_bnd_dv (void)
{
  printf ("\n=== Group: unsplit_bnd_dv (part 3/7: ghost cells, wrap vs clamp) "
          "===\n");
  const int ncx = 4;
  int cases = 0;
  char msg[190];

  // PRECONDITION, measured: a PERIODIC axis must have at least ncx cells.
  // BndL wraps with Row[nx+i] for i = 1-ncx..0, so nx < ncx makes that index
  // <= 0 -- outside the row -- and with no runtime subscript check it reads
  // silently past the buffer.  nx = 3, ncx = 4 already does it.  So the
  // periodic sweep stays at or above ncx, and the degenerate interiors are
  // covered on the CLAMPING path, which has no such requirement.
  struct Case { int nx, ny, xp, yp; };
  std::vector<Case> plan;
  for (int nx : { 4, 5, 7 })
    for (int ny : { 4, 6, 9 })
      for (int xp = 0; xp <= 1; xp++)
        for (int yp = 0; yp <= 1; yp++)
          plan.push_back ({ nx, ny, xp, yp });
  for (int nx : { 1, 2, 3 })
    for (int ny : { 1, 2, 3 })
      plan.push_back ({ nx, ny, 0, 0 });      // clamp only

  for (const Case &cse : plan)
          {
            const int nx = cse.nx, ny = cse.ny, xp = cse.xp, yp = cse.yp;
            // distinct per cell, and exactly representable
            std::vector<double> in ((size_t)nx * ny);
            for (int j = 1; j <= ny; j++)
              for (int i = 1; i <= nx; i++)
                in[(size_t)(j - 1) * nx + (i - 1)] = (double)(100 * j + i);

            sisal_array_t Up = sisal_array_alloc_sized (2, 4,
                                                        (uint64_t)(nx * ny),
                                                        sizeof (double));
            Up.dims[0] = ny; Up.dims[1] = nx;
            Up.lower_bound[0] = 1; Up.lower_bound[1] = 1;
            memcpy (Up.data, in.data (), in.size () * sizeof (double));

            sisal_array_t w = func_MAIN (Up, nx, ny, xp != 0, yp != 0);
            cases++;

            const int W = nx + 2 * ncx, H = ny + 2 * ncx;
            bool ok = w.rank == 2 && (int)w.dims[0] == H && (int)w.dims[1] == W
                      && (int)w.size == W * H
                      && (int)w.lower_bound[0] == 1 - ncx
                      && (int)w.lower_bound[1] == 1 - ncx;
            if (!ok)
              {
                snprintf (msg, sizeof msg,
                          "nx=%d ny=%d xp=%d yp=%d SHAPE rank=%d dims=%lldx%lld "
                          "lb=%d,%d (want %dx%d lb %d,%d)",
                          nx, ny, xp, yp, (int)w.rank, (long long)w.dims[0],
                          (long long)w.dims[1], (int)w.lower_bound[0],
                          (int)w.lower_bound[1], H, W, 1 - ncx, 1 - ncx);
                check (msg, false);
              }
            else
              {
                for (int j = 1 - ncx; ok && j <= ny + ncx; j++)
                  for (int i = 1 - ncx; i <= nx + ncx; i++)
                    {
                      int jj = (j <= 0)   ? (yp ? ny + j : 1)
                               : (j > ny) ? (yp ? j - ny : ny)
                                          : j;
                      int ii = (i <= 0)   ? (xp ? nx + i : 1)
                               : (i > nx) ? (xp ? i - nx : nx)
                                          : i;
                      double want = in[(size_t)(jj - 1) * nx + (ii - 1)];
                      double got = ((const double *)
                                        w.data)[(size_t)(j - (1 - ncx)) * W
                                                + (i - (1 - ncx))];
                      if (got != want) { ok = false; break; }
                    }
                snprintf (msg, sizeof msg,
                          "nx=%d ny=%d xper=%d yper=%d  every ghost cell is the "
                          "cell the rule names",
                          nx, ny, xp, yp);
                check (msg, ok);
              }

            if (Up.data) free (Up.data);
            if (w.data) free (w.data);
          }

  snprintf (msg, sizeof msg,
            "%d combinations (periodic at/above ncx, clamp down to 1x1)", cases);
  check (msg, cases == 45);
}
#endif
#ifdef TEST_UNSPLIT_GRID_DV
// unsplit, part 2 of 7 -- initial conditions (ProbInit / buildplane1 /
// buildplane2) and the starting timestep (InitDt).
//
// A PlaneArray (array of rows) is one flat rank-2 array_dv, dims (ny, nx),
// subscripted [j, i] -- the OUTER axis is J, the row/y direction, which is the
// order the original fixes and every later part inherits.
//
// All closed form: the plane builders choose one of three values per cell by a
// predicate on the cell centre, ProbInit's constants are the Rankine-Hugoniot
// relations, and InitDt is a CFL minimum.  Plus one property that needs no
// formula: buildplane2 differs from buildplane1 only in testing ycen instead of
// xcen, so on a square domain with xcld = ycld the two are TRANSPOSES.
static void test_unsplit_grid_dv (void)
{
  printf ("\n=== Group: unsplit_grid_dv (part 2/7: initial state + CFL dt) "
          "===\n");
  int bad = 0, cases = 0;
  char msg[190];

  struct Cfg { int nx, ny; double xl, xr, yb, yt, gam, den, mach,
                      xc, yc, sdir, spos, rad; const char *nm; };
  const Cfg cfgs[] = {
    { 8,  6, 0.0, 1.0, 0.0, 1.0, 1.4, 10.0, 2.0, 0.5, 0.5,  1.0, 0.25, 0.2,
      "x-shock, cloud inside" },
    { 6,  8, 0.0, 1.0, 0.0, 1.0, 1.4, 10.0, 2.0, 0.5, 0.5, -1.0, 0.25, 0.2,
      "y-shock (buildplane2 path)" },
    { 5,  5, -1.0, 1.0, -1.0, 1.0, 1.6667, 4.0, 3.0, 0.0, 0.0, 1.0, -0.5, 0.6,
      "centred cloud, wide radius" },
    { 4,  4, 0.0, 1.0, 0.0, 1.0, 1.4, 1.0, 1.5, 9.0, 9.0, 1.0, -5.0, 0.1,
      "shock left of everything, cloud far away" },
    // A cell centre sitting EXACTLY on the radius: dx = 0.25 puts centres at
    // 0.125/0.375/0.625/0.875, so with xcld = 0.125, ycld = 0.375 the cell
    // (j=2,i=2) is at distance exactly 0.25.  All binary-exact, so `<=` vs `<`
    // is decided rather than lost in rounding -- without this the boundary of
    // the cloud test is untested (measured: flipping it changed nothing).
    { 4,  4, 0.0, 1.0, 0.0, 1.0, 1.4, 3.0, 2.0, 0.125, 0.375, 1.0, -1.0, 0.25,
      "cell centre exactly ON the cloud radius" },
  };

  for (const Cfg &c : cfgs)
    {
      const double dx = (c.xr - c.xl) / c.nx, dy = (c.yt - c.yb) / c.ny;
      const double cfl = 0.4, tf = 0.75;
      auto r = func_MAIN (c.nx, c.ny, c.xl, c.xr, c.yb, c.yt, c.gam, c.den,
                          c.mach, c.xc, c.yc, c.sdir, c.spos, c.rad, cfl, tf);
      cases++;

      // ---- Rankine-Hugoniot constants, straight from the formulas ----
      const double one = 1.0, two = 2.0, half = 0.5;
      const double gamm1 = c.gam - one, gamp1 = c.gam + one;
      const double rhoamb = one, pamb = one / c.gam;
      const double eamb = rhoamb * (pamb / (gamm1 * rhoamb));
      const double rhocld = rhoamb * c.den;
      const double ecld = rhocld * (pamb / (gamm1 * rhocld));
      const double ashk = sqrt (c.gam * pamb / rhoamb);
      const double ushk = ashk * two * (c.mach * c.mach - one) / (gamp1 * c.mach);
      const double rhoshk = rhoamb * (gamp1 * c.mach * c.mach)
                            / (gamm1 * c.mach * c.mach + two);
      const double pshk = pamb * (one + (two * c.gam * (c.mach * c.mach - one)) / gamp1);
      const double eshk = rhoshk * (pshk / (gamm1 * rhoshk) + half * ushk * ushk);
      const double unshk = rhoshk * ushk;

      auto cell = [&] (int j, int i, double vshk, double vcld, double vamb) {
        double xcen = c.xl + dx * ((double)i - 0.5);
        double ycen = c.yb + dy * ((double)j - 0.5);
        double test = (c.sdir > 0.0) ? xcen : ycen;      // plane1 vs plane2
        if (test < c.spos) return vshk;
        double d2 = (xcen - c.xc) * (xcen - c.xc) + (ycen - c.yc) * (ycen - c.yc);
        return (d2 <= c.rad * c.rad) ? vcld : vamb;
      };

      auto planeok = [&] (sisal_array_t a, double vshk, double vcld, double vamb) {
        if (a.rank != 2 || (int)a.dims[0] != c.ny || (int)a.dims[1] != c.nx
            || (int)a.size != c.nx * c.ny)
          return false;
        for (int j = 1; j <= c.ny; j++)
          for (int i = 1; i <= c.nx; i++)
            if (((const double *)a.data)[(j - 1) * c.nx + (i - 1)]
                != cell (j, i, vshk, vcld, vamb))
              return false;
        return true;
      };

      if (!planeok (r.U1, rhoshk, rhocld, rhoamb)) bad++;   // density
      if (!planeok (r.U2, unshk, 0.0, 0.0)) bad++;          // normal momentum
      if (!planeok (r.U3, 0.0, 0.0, 0.0)) bad++;            // transverse
      if (!planeok (r.U4, eshk, ecld, eamb)) bad++;         // energy

      // ---- InitDt: the CFL minimum over every cell ----
      double best = 0;
      bool first = true;
      for (int j = 1; j <= c.ny; j++)
        for (int i = 1; i <= c.nx; i++)
          {
            double rho = cell (j, i, rhoshk, rhocld, rhoamb);
            double ux = fabs (cell (j, i, unshk, 0.0, 0.0));
            double uy = 0.0;
            double eng = cell (j, i, eshk, ecld, eamb);
            double usq = (ux * ux + uy * uy) / rho;
            double p = (eng - 0.5 * usq) * (c.gam - 1.0);
            double cc = sqrt (c.gam * p / rho);
            double d1 = dx / (cc + ux / rho), d2 = dy / (cc + uy / rho);
            double m = d1 < d2 ? d1 : d2;
            if (first || m < best) { best = m; first = false; }
          }
      if (fabs (r.dt - best * cfl * tf) > 1e-12 * fabs (best * cfl * tf) + 1e-15)
        {
          printf ("  %-34s dt %.17g want %.17g\n", c.nm, r.dt, best * cfl * tf);
          bad++;
        }

      snprintf (msg, sizeof msg, "%-34s planes are %dx%d and match cell by cell",
                c.nm, c.ny, c.nx);
      check (msg, bad == 0);
      bad = 0;

      if (r.U1.data) free (r.U1.data);
      if (r.U2.data) free (r.U2.data);
      if (r.U3.data) free (r.U3.data);
      if (r.U4.data) free (r.U4.data);
      if (r.p1.data) free (r.p1.data);
      if (r.p2.data) free (r.p2.data);
    }

  // ---- the transpose property, on a square domain with xcld == ycld ----
  {
    const int n = 7;
    auto r = func_MAIN (n, n, -1.0, 1.0, -1.0, 1.0, 1.4, 8.0, 2.5, 0.25, 0.25,
                        1.0, 0.1, 0.5, 0.4, 1.0);
    bool ok = r.p1.rank == 2 && r.p2.rank == 2 && (int)r.p1.size == n * n
              && (int)r.p2.size == n * n;
    for (int j = 0; ok && j < n; j++)
      for (int i = 0; i < n; i++)
        if (((const double *)r.p1.data)[j * n + i]
            != ((const double *)r.p2.data)[i * n + j])
          { ok = false; break; }
    check ("buildplane2 is buildplane1 transposed (square domain, xcld==ycld)",
           ok);

    // and the markers prove all three branches actually fire
    bool saw[4] = { false, false, false, false };
    for (int k = 0; k < n * n; k++)
      {
        int v = (int)((const double *)r.p1.data)[k];
        if (v >= 1 && v <= 3) saw[v] = true;
      }
    check ("all three cell branches fire (shock / cloud / ambient)",
           saw[1] && saw[2] && saw[3]);

    if (r.U1.data) free (r.U1.data);
    if (r.U2.data) free (r.U2.data);
    if (r.U3.data) free (r.U3.data);
    if (r.U4.data) free (r.U4.data);
    if (r.p1.data) free (r.p1.data);
    if (r.p2.data) free (r.p2.data);
  }
  snprintf (msg, sizeof msg, "%d configurations checked", cases);
  check (msg, cases == 5);
}
#endif
#ifdef TEST_STREAM_RECORD_DV
// stream_record -- a stream whose element is a RECORD.  Every other stream test
// carries a scalar; a record element came out `sisal_generator<sisal_array_t>`
// and would not compile, because a record's C type is
// `struct struct_rec_<its own typemap id>` and the value-based type mapper only
// sees the fields.  This is the one backend gap that stops unsplit.sis (its
// PlotStreamType is a stream of Plot records) from compiling.
//
// The lazy builders follow the documented for-initial stream-gather rules
// (docs/loop_behavior_comparison.md, and the model stream_integers_dv uses):
// the SEED is gathered, then every body value including the final
// out-of-bounds one -- so Chain(n) yields n+1 elements.
static void test_stream_record_dv (void)
{
  printf ("\n=== Group: stream_record_dv (stream[record], mixed field types) "
          "===\n");
  int bad = 0;
  for (int32_t n : { 0, 1, 3, 6 })
    {
      auto r = func_MAIN (n);

      // Two() is the literal stream: (1,2) and (3,4)
      if (r.ax != 1 + 3 || r.ay != 2 + 4) bad++;

      // Chain(n): Pt(i, 10i) for i = 1 .. n+1  (seed + each body value)
      int32_t wx = 0, wy = 0;
      for (int32_t i = 1; i <= n + 1; i++) { wx += i; wy += 10 * i; }
      if (r.bx != wx || r.by != wy) bad++;

      // Mixed(n): the elements themselves, drained field by field.  The
      // boolean and the double are what a wrong element type cannot fake.
      std::vector<sr_mix> got;
      for (sisal_generator<sr_mix> g = r.mixed; !sisal_stream_empty_pred (g);
           g = sisal_stream_rest (g))
        got.push_back (sisal_stream_first<sr_mix> (g));
      bool ok = (int)got.size () == n + 1;
      for (int32_t i = 1; ok && i <= n + 1; i++)
        {
          const sr_mix &m = got[i - 1];
          ok = m.n == i && m.v == (double)i / 4.0 && m.ok == (i % 2 == 0);
        }
      if (!ok)
        {
          printf ("  n=%d mixed stream: got %zu elements, wanted %d\n", n,
                  got.size (), n + 1);
          bad++;
        }
    }
  check ("record streams (literal, lazy, mixed fields) match the reference",
         bad == 0);

  // spell out the two facts the type fix turns on
  {
    auto r = func_MAIN (3);
    check ("fields survive the round trip: Two() sums to (4,6)",
           r.ax == 4 && r.ay == 6);
    std::vector<sr_mix> got;
    for (sisal_generator<sr_mix> g = r.mixed; !sisal_stream_empty_pred (g);
         g = sisal_stream_rest (g))
      got.push_back (sisal_stream_first<sr_mix> (g));
    check ("a mixed-width element keeps int, double and bool distinct",
           got.size () == 4 && got[1].n == 2 && got[1].v == 0.5
               && got[1].ok == true && got[0].ok == false);
  }
}
#endif
#ifdef TEST_UNSPLIT_SCALARS_DV
// unsplit, part 1 of 7 -- the scalar and 1-D helper layer of the LLNL AMR hydro
// integrator (test/unit/unsplit.sis, 1935 lines).  Everything here is a closed
// form, so each reference is just the formula.
//
// Two of them are pinned deliberately because later parts build on them:
//   * sign(x,y) is FORTRAN's SIGN written as `y >= 0 ? |x| : -|x|`, which is NOT
//     copysign at the boundary -- IEEE has -0.0 >= 0.0 TRUE, so sign(x,-0.0) is
//     +|x| here and -|x| under copysign.  Fed -0.0 on purpose below.
//   * acopy(A,lo,hi) PRESERVES THE ORIGIN: `for i in lo,hi returns array_dv of
//     A[i]` is indexed lo..hi, so lower_bound comes back as lo, not 1.  Callers
//     index the slice by the original i, so re-basing would shift later stages.
static void test_unsplit_scalars_dv (void)
{
  printf ("\n=== Group: unsplit_scalars_dv (part 1/7: scalar + 1-D helpers) "
          "===\n");
  const int N = 8;
  std::vector<double> A (N);
  for (int k = 0; k < N; k++) A[k] = 1.5 + 2.25 * k;   // exact in binary

  int bad = 0, cases = 0;
  const double vals[] = { 3.5, -3.5, 0.0, -0.0, 1e-9, -2.75 };
  for (int lo = 1; lo <= N; lo++)
    for (int hi = lo; hi <= N; hi++)
      for (double y : vals)
        {
          const double x = -2.75, xl = -1.25, dx = 0.5, yb = 0.75, dyy = 0.25;
          const double xcl = 0.5, ycl = -0.25, xq = 2.0, yq = -1.5;
          const int i = 3, j = 5;
          sisal_array_t a = sisal_array_alloc_sized (1, 4, (uint64_t)N,
                                                     sizeof (double));
          memcpy (a.data, A.data (), (size_t)N * sizeof (double));
          auto r = func_MAIN (a, lo, hi, i, j, x, y, xl, dx, yb, dyy, xq, xcl,
                              yq, ycl);
          cases++;

          // acopy: A[lo..hi], re-based to 1
          int n = hi - lo + 1;
          bool ok = (int)r.slice.size == n && r.slice.rank == 1
                    && (int)r.slice.lower_bound[0] == lo;   // origin preserved
          for (int k = 0; ok && k < n; k++)
            ok = ((const double *)r.slice.data)[k] == A[lo - 1 + k];
          if (!ok) bad++;

          // sign as WRITTEN: y >= 0 -> |x|, else -|x|
          double want_sgn = (y >= 0.0) ? fabs (x) : -fabs (x);
          if (r.sgn != want_sgn) bad++;
          if (r.sq != x * x) bad++;
          if (r.xc != xl + dx * ((double)i - 0.5)) bad++;
          if (r.yc != yb + dyy * ((double)j - 0.5)) bad++;
          if (r.d2 != (xq - xcl) * (xq - xcl) + (yq - ycl) * (yq - ycl)) bad++;

          if (a.data) free (a.data);
          if (r.slice.data) free (r.slice.data);
        }

  char msg[160];
  snprintf (msg, sizeof msg,
            "all helpers match their closed forms over %d cases", cases);
  check (msg, bad == 0);

  // spell out the two that later parts depend on
  {
    sisal_array_t a = sisal_array_alloc_sized (1, 4, (uint64_t)N, sizeof (double));
    memcpy (a.data, A.data (), (size_t)N * sizeof (double));
    auto r = func_MAIN (a, 3, 5, 3, 5, -2.75, -0.0, -1.25, 0.5, 0.75, 0.25,
                        2.0, 0.5, -1.5, -0.25);
    check ("sign(x, -0.0) is +|x| (y >= 0 is true for -0.0), not copysign",
           r.sgn == 2.75);
    check ("acopy(A,3,5) keeps its origin: 3 elements, lower_bound 3",
           (int)r.slice.size == 3 && (int)r.slice.lower_bound[0] == 3
               && ((const double *)r.slice.data)[0] == A[2]
               && ((const double *)r.slice.data)[2] == A[4]);
    if (a.data) free (a.data);
    if (r.slice.data) free (r.slice.data);
  }
  {
    sisal_array_t a = sisal_array_alloc_sized (1, 4, (uint64_t)N, sizeof (double));
    memcpy (a.data, A.data (), (size_t)N * sizeof (double));
    auto r = func_MAIN (a, 1, 1, 3, 5, -2.75, 0.0, -1.25, 0.5, 0.75, 0.25,
                        2.0, 0.5, -1.5, -0.25);
    check ("sign(x, +0.0) is +|x| too", r.sgn == 2.75);
    if (a.data) free (a.data);
    if (r.slice.data) free (r.slice.data);
  }
}
#endif
#ifdef TEST_CONFORM_ERROR_DV
// conform_error -- the ERROR channel on its FAILING path.
//
// Testing an abort needs a child process: the check ends in abort(), so the
// only way to assert it fired without killing the harness is to fork, let the
// child do the non-conforming call, and inspect how it died.  The child's
// stderr goes to /dev/null so the expected diagnostic does not look like a
// failure in the log.
static bool conform_child_aborts (int na, int nb)
{
  fflush (stdout);
  pid_t pid = fork ();
  if (pid == 0)
    {
      freopen ("/dev/null", "w", stderr);
      std::vector<int32_t> A (na), B (nb);
      for (int i = 0; i < na; i++) A[i] = i + 1;
      for (int i = 0; i < nb; i++) B[i] = 10 * (i + 1);
      sisal_array_t a = sisal_array_alloc_empty (1, 6, (uint64_t)na);
      sisal_array_t b = sisal_array_alloc_empty (1, 6, (uint64_t)nb);
      memcpy (a.data, A.data (), (size_t)na * sizeof (int32_t));
      memcpy (b.data, B.data (), (size_t)nb * sizeof (int32_t));
      sisal_array_t r = func_MAIN (a, b);
      _exit (r.size == 0 ? 2 : 0);      // reached here => no abort
    }
  int st = 0;
  waitpid (pid, &st, 0);
  return WIFSIGNALED (st) && WTERMSIG (st) == SIGABRT;
}
static void test_conform_error_dv (void)
{
  printf ("\n=== Group: conform_error_dv (the ERROR channel, on its failing "
          "path) ===\n");

  // the passing branch still has to compute
  const int N = 5;
  std::vector<int32_t> A (N), B (N);
  for (int i = 0; i < N; i++) { A[i] = i + 1; B[i] = 10 * (i + 1); }
  sisal_array_t a = sisal_array_alloc_empty (1, 6, N);
  sisal_array_t b = sisal_array_alloc_empty (1, 6, N);
  memcpy (a.data, A.data (), N * sizeof (int32_t));
  memcpy (b.data, B.data (), N * sizeof (int32_t));
  sisal_array_t r = func_MAIN (a, b);
  bool ok = (int)r.size == N;
  for (int i = 0; ok && i < N; i++)
    ok = ((const int32_t *)r.data)[i] == A[i] + B[i];
  check ("conforming extents still compute a + b", ok);

  // and both directions of mismatch have to be caught, not padded
  check ("longer LEFT operand aborts  (5 + 3)", conform_child_aborts (5, 3));
  check ("longer RIGHT operand aborts (3 + 5)", conform_child_aborts (3, 5));
  check ("a single extra element is caught (5 + 4)", conform_child_aborts (5, 4));

  if (a.data) free (a.data);
  if (b.data) free (b.data);
  if (r.data) free (r.data);
}
#endif
#ifdef TEST_BULK_OPS_DV
// bulk_ops -- the whole-array (APL-style) operator battery of
// test/unit/bulk_ops.sis, which describes itself as "parse-only stubs".  It
// proved the operators PARSE; this proves what they COMPUTE.
//
// Every reference below is the STANDARD meaning of the operator, written
// independently -- not a snapshot.  That is what let three of the 35 be
// identified as wrong rather than absorbed: SCAN dropped the total (af35d42)
// and ARGMAX/ARGMIN answered 0 for every input.  Both are fixed and covered
// here; what remains uncovered has no lowering at all and is listed in the
// .sis; all 58 now agree exactly.
//
// The elementwise eight could not even be RETURNED alongside the rest before
// 34f06a7 (the BROADCAST_ERROR panic edge typed result port 1 as int32_t), so
// their presence in one multi-output call is itself the regression pin.
struct bulk_case {
  std::vector<int32_t> A, B;
  std::vector<char> Mk;
  std::vector<float> X, Y;
  int32_t n, lo, hi, k, z, f;
  const char *nm;
};
static void test_bulk_ops_dv (void)
{
  printf ("\n=== Group: bulk_ops_dv (58 whole-array primitives vs standard "
          "definitions) ===\n");
  const std::vector<bulk_case> cases = {
    { { 3, -1, 4, 0, 5 }, { 2, -1, 7, 0, 1 }, { 1, 0, 1, 0, 1 },
      { 1.5f, 2.5f, 3.5f, 4.5f, 5.5f }, { 10, 20, 30, 40, 50 },
      2, 2, 4, 2, 100, 9, "mixed signs, a zero" },
    { { 1, 2, 3, 4, 5, 6 }, { 6, 5, 4, 3, 2, 1 }, { 1, 1, 0, 0, 1, 1 },
      { 1, 2, 3, 4, 5, 6 }, { -1, -2, -3, -4, -5, -6 },
      3, 1, 6, 4, 0, -1, "ascending, full-range reduction" },
    { { -2, -2, 5 }, { 1, 0, -3 }, { 0, 0, 1 }, { 9, 8, 7 }, { 1, 2, 3 },
      1, 1, 3, 1, -5, 0, "short, repeated minimum" },
  };

  // 2x3, 2x3 and 3x2 reals are fixed across cases: only PERMUTE / INNERPRODUCT
  // read them, and their shapes are independent of the rank-1 inputs.
  std::vector<float> Mm = { 1, 2, 3, 4, 5, 6 };
  std::vector<float> Pm = { 1, 2, 3, 4, 5, 6 };
  std::vector<float> Qm = { 7, 8, 9, 10, 11, 12 };

  int bad = 0;
  char msg[160];
  for (const auto &c : cases)
    {
      const int N = (int)c.A.size ();
      auto mkI = [] (const std::vector<int32_t> &v) {
        sisal_array_t s = sisal_array_alloc_empty (1, 6, v.size ());
        memcpy (s.data, v.data (), v.size () * sizeof (int32_t));
        return s;
      };
      auto mkF = [] (const std::vector<float> &v) {
        sisal_array_t s = sisal_array_alloc_empty (1, 8, v.size ());
        memcpy (s.data, v.data (), v.size () * sizeof (float));
        return s;
      };
      auto mkF2 = [] (const std::vector<float> &v, int r, int cc) {
        sisal_array_t s = sisal_array_alloc_empty (2, 8, v.size ());
        s.dims[0] = r; s.dims[1] = cc;
        s.lower_bound[0] = 1; s.lower_bound[1] = 1;
        memcpy (s.data, v.data (), v.size () * sizeof (float));
        return s;
      };
      sisal_array_t sa = mkI (c.A), sb = mkI (c.B);
      sisal_array_t sx = mkF (c.X), sy = mkF (c.Y);
      // a boolean array_dv element is ONE byte; alloc_empty's legacy table
      // would say 4 and stride the mask wrong
      sisal_array_t sm = sisal_array_alloc_sized (1, 1, N, sizeof (bool));
      for (int i = 0; i < N; i++) ((bool *)sm.data)[i] = c.Mk[i];
      sisal_array_t sM = mkF2 (Mm, 2, 3), sP = mkF2 (Pm, 2, 3),
                    sQ = mkF2 (Qm, 3, 2);

      auto r = func_MAIN (sa, sb, sm, sx, sy, sM, sP, sQ, c.n, c.lo, c.hi, c.k,
                          c.z, c.f);

      int local = 0;
      auto ci = [&] (sisal_array_t s, const std::vector<int32_t> &w) {
        if ((int)s.size != (int)w.size ()) { local++; return; }
        for (size_t i = 0; i < w.size (); i++)
          if (((const int32_t *)s.data)[i] != w[i]) { local++; return; }
      };
      auto cf = [&] (sisal_array_t s, const std::vector<float> &w) {
        if ((int)s.size != (int)w.size ()) { local++; return; }
        for (size_t i = 0; i < w.size (); i++)
          if (((const float *)s.data)[i] != w[i]) { local++; return; }
      };
      auto cs = [&] (int32_t got, int32_t want) { if (got != want) local++; };

      std::vector<int32_t> w;
      w.clear (); for (int i = 0; i < N; i++) w.push_back (c.A[i] + c.B[i]); ci (r.add, w);
      w.clear (); for (int i = 0; i < N; i++) w.push_back (c.A[i] - c.B[i]); ci (r.sub, w);
      w.clear (); for (int i = 0; i < N; i++) w.push_back (c.A[i] * c.B[i]); ci (r.mul, w);
      w.clear (); for (int i = 0; i < N; i++) w.push_back (-c.A[i]);         ci (r.neg, w);
      for (int i = 0; i < N; i++)
        {
          if (((const bool *)r.eq.data)[i] != (c.A[i] == c.B[i])) local++;
          if (((const bool *)r.lt.data)[i] != (c.A[i] < c.B[i])) local++;
        }
      w.clear (); for (int i = 0; i < N; i++) w.push_back (c.A[i] + c.n); ci (r.adds, w);
      w.clear (); for (int i = 0; i < N; i++) w.push_back (c.A[i] * c.n); ci (r.muls, w);

      {
        int s = 0, p = 1, mn = c.A[0], mx = c.A[0];
        for (int i = 0; i < N; i++)
          { s += c.A[i]; p *= c.A[i]; mn = std::min (mn, c.A[i]); mx = std::max (mx, c.A[i]); }
        cs (r.sum, s); cs (r.prod, p); cs (r.least, mn); cs (r.greatest, mx);
        int sr = 0, lr = c.A[c.lo - 1];          // 1-based, inclusive
        for (int i = c.lo; i <= c.hi; i++) { sr += c.A[i-1]; lr = std::min (lr, c.A[i-1]); }
        cs (r.sumr, sr); cs (r.leastr, lr);
      }

      w.clear (); for (int i = 0; i < N; i++) w.push_back (-c.A[i]); ci (r.map, w);
      { int s = c.z; for (int i = 0; i < N; i++) s += c.A[i];
        cs (r.foldl, s); cs (r.foldr, s); }   // + is associative: both fold the same
      // inclusive scan: out[0] = a[0], out[i] = f(out[i-1], a[i])
      w.clear (); { int s = 0; for (int i = 0; i < N; i++) { s += c.A[i]; w.push_back (s); } }
      ci (r.scan, w);
      // the same with a NON-COMMUTATIVE f, which is what pins LEFT association:
      // right association would give a different sequence entirely
      w.clear (); { int s = c.A[0]; w.push_back (s);
                    for (int i = 1; i < N; i++) { s -= c.A[i]; w.push_back (s); } }
      ci (r.scans, w);

      w.clear (); for (int i = 0; i < c.n; i++) w.push_back (c.A[i]);       ci (r.take, w);
      w.clear (); for (int i = c.n; i < N; i++) w.push_back (c.A[i]);       ci (r.drop, w);
      w.clear (); for (int i = 0; i < N; i++) w.push_back (c.A[(i + c.k) % N]); ci (r.rot, w);
      w.clear (); for (int i = N - 1; i >= 0; i--) w.push_back (c.A[i]);    ci (r.rev, w);
      w.clear (); for (int i = 0; i < N; i++) if (c.Mk[i]) w.push_back (c.A[i]); ci (r.comp, w);
      w = c.A; std::sort (w.begin (), w.end ());                            ci (r.sort, w);
      // index of the FIRST extremum, on the array's own base (here 1-based)
      { int mi = 0, ni = 0;
        for (int i = 1; i < N; i++)
          { if (c.A[i] > c.A[mi]) mi = i; if (c.A[i] < c.A[ni]) ni = i; }
        cs (r.argmax, mi + 1); cs (r.argmin, ni + 1); }
      w.clear (); for (int i = 0; i < N; i++) if (c.A[i] != 0) w.push_back (i + 1);
      ci (r.nonzero, w);                        // 1-based INDICES, not values
      { std::vector<float> wf;
        for (int i = 0; i < N; i++) wf.push_back (c.Mk[i] ? c.X[i] : c.Y[i]);
        cf (r.where, wf); }

      w.clear (); for (int v : c.A) w.push_back (v);
      for (int v : c.B) w.push_back (v);                                    ci (r.concat, w);
      w.clear (); for (int t = 0; t < c.n; t++) for (int v : c.A) w.push_back (v);
      ci (r.tile, w);
      w.clear (); for (int i = 0; i < c.lo; i++) w.push_back (0);
      for (int v : c.A) w.push_back (v);
      for (int i = 0; i < c.hi; i++) w.push_back (0);                       ci (r.pad, w);
      w.clear (); for (int i = 0; i < c.lo; i++) w.push_back (c.f);
      for (int v : c.A) w.push_back (v);
      for (int i = 0; i < c.hi; i++) w.push_back (c.f);                     ci (r.padf, w);
      w.clear (); for (int i = 0; i + 3 <= N; i++)
        w.push_back (c.A[i] + c.A[i+1] + c.A[i+2]);                         ci (r.stencil, w);

      { std::vector<float> wf (4);
        for (int i = 0; i < 2; i++)
          for (int j = 0; j < 2; j++)
            { float s = 0;
              for (int t = 0; t < 3; t++) s += Pm[i*3+t] * Qm[t*2+j];
              wf[i*2+j] = s; }
        cf (r.inner, wf); }
      { std::vector<float> wf (6);
        for (int i = 0; i < 2; i++)
          for (int j = 0; j < 3; j++) wf[j*2+i] = Mm[i*3+j];
        cf (r.perm, wf); }

      // ---- statistics, folds, cumulative and shape --------------------
      { double mn = 0; for (int i = 0; i < N; i++) mn += c.X[i]; mn /= N;
        double vr = 0; for (int i = 0; i < N; i++) vr += (c.X[i]-mn)*(c.X[i]-mn);
        vr /= N;                                   // POPULATION variance
        double nr = 0;
        for (int i = 0; i < N; i++) {
          double v = std::fabs ((double)c.X[i]);
          nr += (c.n == 1) ? v : (c.n == 2) ? v*v : std::pow (v, (double)c.n);
        }
        nr = (c.n == 1) ? nr : (c.n == 2) ? std::sqrt (nr)
                                          : std::pow (nr, 1.0/(double)c.n);
        if (std::fabs (r.mean - mn) > 1e-4) local++;
        if (std::fabs (r.var  - vr) > 1e-3) local++;
        if (std::fabs (r.sd - std::sqrt (vr)) > 1e-4) local++;
        if (std::fabs (r.norm - nr) > 1e-3) local++; }

      { bool any = false, all = true;
        for (int i = 0; i < N; i++) { if (c.Mk[i]) any = true; else all = false; }
        if (r.any_m != any) local++;
        if (r.all_m != all) local++;
        if (r.all_true != true) local++;      // ALL(a = a)
        if (r.any_false != false) local++; }  // ANY(a < a)

      w.clear (); { int32_t s2 = 0; for (int i = 0; i < N; i++) { s2 += c.A[i]; w.push_back (s2); } }
      ci (r.cumsum, w);
      w.clear (); { int32_t s2 = 1; for (int i = 0; i < N; i++) { s2 *= c.A[i]; w.push_back (s2); } }
      ci (r.cumprod, w);

      // M is 2x3: RAVEL flattens it to 6 in row-major order
      { std::vector<float> wf (Mm.begin (), Mm.end ()); cf (r.ravel, wf);
        if (r.ravel.rank != 1 || (int)r.ravel.dims[0] != 6) local++; }
      // EXPAND at axis 0 makes a 1 x N block; SQUEEZE must undo it exactly
      if (r.expand.rank != 2 || (int)r.expand.dims[0] != 1
          || (int)r.expand.dims[1] != N) local++;
      if (r.sq_round.rank != 1 || (int)r.sq_round.dims[0] != N
          || (int)r.sq_round.size != N) local++;
      { std::vector<float> wf (c.X.begin (), c.X.end ()); cf (r.sq_round, wf); }

      // GRADE_UP/GRADE_DOWN: the STABLE sorting permutation, 1-based
      { std::vector<int32_t> idx (N); for (int i = 0; i < N; i++) idx[i] = i;
        std::stable_sort (idx.begin (), idx.end (),
                          [&] (int32_t p1, int32_t p2) { return c.A[p1] < c.A[p2]; });
        w.clear (); for (int i : idx) w.push_back (i + 1); ci (r.gup, w); }
      { std::vector<int32_t> idx (N); for (int i = 0; i < N; i++) idx[i] = i;
        std::stable_sort (idx.begin (), idx.end (),
                          [&] (int32_t p1, int32_t p2) { return c.A[p1] > c.A[p2]; });
        w.clear (); for (int i : idx) w.push_back (i + 1); ci (r.gdn, w); }

      // ---- REDUCE_AXIS on the fixed 2x3 M = [1 2 3; 4 5 6] --------------
      // axis 0 collapses the 2 ROWS (3 results), axis 1 the 3 COLUMNS (2), so
      // the result LENGTH already says which axis went away.
      { std::vector<float> w0 = {5,7,9}, w1 = {6,15};
        cf (r.ax_s0, w0);                                  // SUM axis 0
        cf (r.ax_s1, w1);                                  // SUM axis 1
        std::vector<float> p1 = {6,120};   cf (r.ax_p1, p1);
        std::vector<float> l0 = {1,2,3};   cf (r.ax_l0, l0);
        std::vector<float> g1 = {3,6};     cf (r.ax_g1, g1);
        std::vector<float> m0 = {2.5f,3.5f,4.5f}; cf (r.ax_m0, m0);
        std::vector<float> mx = {3,3};     cf (r.ax_amax1, mx);   // 1-based
        std::vector<float> mn = {1,1,1};   cf (r.ax_amin0, mn); }

      // OUTERPRODUCT: N x N of f(a[i], b[j]).  The subtracting one is what
      // pins the OPERAND ORDER -- f(b[j], a[i]) would negate every cell.
      { std::vector<int32_t> wa, ws;
        for (int i = 0; i < N; i++)
          for (int j = 0; j < N; j++)
            { wa.push_back (c.A[i] + c.B[j]); ws.push_back (c.A[i] - c.B[j]); }
        ci (r.op_add, wa); ci (r.op_sub, ws);
        if (r.op_add.rank != 2 || (int)r.op_add.dims[0] != N
            || (int)r.op_add.dims[1] != N) local++; }

      snprintf (msg, sizeof msg, "%-34s all 58 primitives match", c.nm);
      check (msg, local == 0);
      bad += local;
    }
  snprintf (msg, sizeof msg, "no mismatches across %zu input sets",
            cases.size ());
  check (msg, bad == 0);
}
#endif
#ifdef TEST_NANU_DV
// nanu -- Dave Cann's A * B = C matrix multiply (test/unit/nanu.sis, LLNL 1991).
//
// The original's own oracle is too weak to be worth reproducing alone: Setupa
// builds the IDENTITY, so C = A * B is just B and Main returns 0 mismatches --
// but a transposed subscript in the inner reduction ALSO returns B when A is
// the identity.  So the port keeps that self-check and additionally multiplies
// a non-symmetric G[i,j] = i*10 + j by the same B, which a real matmul
// reference here has to match.  Transposing G in the reference fails 12 of the
// checks; the identity leg would not have noticed at all.
//
// Be's arithmetic is the second thing pinned.  `s*i/(i-10)` is an INTEGER
// division widened by real(...), not a real division -- Be(5,5) is
// 0 -1 -2 -3 -5, i.e. truncation TOWARD ZERO for the negative divisors
// (5*2/-8 = -1, not -2).  Substituting real division in the reference fails 45
// checks.  n = 10 and 12 exercise the (i-10) = 0 guard.
static std::vector<float> nanu_be (int n, int s)
{
  std::vector<float> v (n);
  for (int i = 1; i <= n; i++)
    {
      int den = (i - 10 == 0) ? 1 : (i - 10);
      v[i - 1] = (float)(s * i / den);          // INTEGER division, then widen
    }
  return v;
}
static void test_nanu_dv (void)
{
  printf ("\n=== Group: nanu_dv (A*B=C; identity leg plus a non-symmetric "
          "multiply) ===\n");
  int n_bad = 0, n_cnt_bad = 0, cases = 0;
  char msg[160];
  for (int n : { 1, 3, 5, 10, 12 })
    for (int s : { 3, 5, 7 })
      {
        const auto be = nanu_be (n, s);
        std::vector<float> B (n * n), G (n * n), C (n * n), D (n * n);
        for (int i = 0; i < n; i++)
          for (int j = 0; j < n; j++)
            {
              B[i * n + j] = be[j];                       // every row is Be
              G[i * n + j] = (float)((i + 1) * 10 + (j + 1));
            }
        for (int i = 0; i < n; i++)
          for (int k = 0; k < n; k++)
            {
              float c = 0, d = 0;
              for (int j = 0; j < n; j++)
                {
                  c += ((i == j) ? 1.0f : 0.0f) * B[j * n + k];
                  d += G[i * n + j] * B[j * n + k];
                }
              C[i * n + k] = c;
              D[i * n + k] = d;
            }

        auto r = func_MAIN (n, s);
        cases++;
        auto same = [&] (sisal_array_t a, const std::vector<float> &want) {
          if ((int)a.size != n * n || a.rank != 2 || (int)a.dims[0] != n
              || (int)a.dims[1] != n)
            return false;
          for (int t = 0; t < n * n; t++)
            if (((const float *)a.data)[t] != want[t]) return false;  // small ints: exact
          return true;
        };
        if (!same (r.B, B) || !same (r.C, C) || !same (r.D, D) || !same (r.G, G))
          n_bad++;
        if (r.ncnt != 0) n_cnt_bad++;

        if (r.B.data) free (r.B.data);
        if (r.C.data) free (r.C.data);
        if (r.D.data) free (r.D.data);
        if (r.G.data) free (r.G.data);
      }
  snprintf (msg, sizeof msg,
            "all four matrices match the reference over %d (n,s) cases", cases);
  check (msg, n_bad == 0);
  check ("identity leg: C == B, so the program's own mismatch count is 0",
         n_cnt_bad == 0);

  // Spell the two pinned facts out, so a regression names itself.
  {
    auto r = func_MAIN (5, 5);
    const float want_be[5] = { 0, -1, -2, -3, -5 };
    bool ok = r.B.size == 25;
    for (int j = 0; ok && j < 5; j++)
      ok = ((const float *)r.B.data)[j] == want_be[j];
    check ("Be(5,5) is 0 -1 -2 -3 -5 (INTEGER division, truncating to zero)", ok);
    // D[1,k] = sum_j G[1,j]*B[j,k] = be[k] * (10+1 + 10+2 + ... ) -- not B
    float row = 0;
    for (int j = 1; j <= 5; j++) row += (float)(10 + j);
    bool nz = r.D.size == 25
              && ((const float *)r.D.data)[1] == want_be[1] * row
              && ((const float *)r.D.data)[1] != ((const float *)r.B.data)[1];
    check ("the non-symmetric leg really multiplies (D != B)", nz);
    if (r.B.data) free (r.B.data);
    if (r.C.data) free (r.C.data);
    if (r.D.data) free (r.D.data);
    if (r.G.data) free (r.G.data);
  }
}
#endif
#ifdef TEST_CROSSOVERS_DV
// crossovers -- the crossed-edge geometry of the TSP annealing code
// (test/unit/crossovers.sis).  A crossing is a fixed 2 x 2 block of node
// indices, so a cross list is a rank-3 array_dv (ncross x 2 x 2) whose COUNT is
// data-dependent but whose shape is not ragged.  Find_All_Crosses builds it by
// accumulating a LIST (its candidate set is a triangle) and packing with
// array_addh; Check_Crossed and Remove_Edge build it dense-then-COMPRESS.
//
// The reference is an independent segment-intersection test: the Sisal side
// solves the two parametric equations by Cramer (the original's arithmetic),
// this side uses ORIENTATION predicates.  They agree exactly for non-parallel
// segments, which is the only case either calls a crossing.
//
// This group also pins the array_addh leading-axis lower bound.  The packed
// rank-3 is subscripted again by Remove_Edge (C[k,1,1] ...), so if the axis
// created by the first append ever goes back to 0-based, `rem` reads one slab
// high and this fails -- which is exactly how the bug was found.
struct xo_pt { int x, y; };
typedef std::array<int, 4> xo_cross;              // a1 a2 b1 b2
static long long xo_orient (long long px, long long py, long long qx,
                            long long qy, long long rx, long long ry)
{
  return (qx - px) * (ry - py) - (qy - py) * (rx - px);
}
static int xo_sgn (long long v) { return v > 0 ? 1 : (v < 0 ? -1 : 0); }
static bool xo_crossed (int a1, int a2, int b1, int b2,
                        const std::vector<xo_pt> &N)
{
  // edges sharing a node are settled on the INDICES, before any geometry
  if (a1 == b2 || a2 == b1 || a1 == b1 || a2 == b2) return false;
  const xo_pt &A = N[a1], &B = N[a2], &C = N[b1], &D = N[b2];
  long long cr = (long long)(B.x - A.x) * (D.y - C.y)
                 - (long long)(B.y - A.y) * (D.x - C.x);
  if (cr == 0) return false;                      // parallel is not a crossing
  int d1 = xo_sgn (xo_orient (A.x, A.y, B.x, B.y, C.x, C.y));
  int d2 = xo_sgn (xo_orient (A.x, A.y, B.x, B.y, D.x, D.y));
  int d3 = xo_sgn (xo_orient (C.x, C.y, D.x, D.y, A.x, A.y));
  int d4 = xo_sgn (xo_orient (C.x, C.y, D.x, D.y, B.x, B.y));
  return d1 * d2 <= 0 && d3 * d4 <= 0;            // closed: touching counts
}
static std::vector<xo_cross> xo_find_all (const std::vector<int> &it,
                                          const std::vector<xo_pt> &N)
{
  std::vector<xo_cross> out;
  const int L = (int)it.size ();
  for (int I = 1; I <= L - 3; I++)
    for (int J = I + 2; J <= L - 1; J++)
      if (xo_crossed (it[I - 1], it[I], it[J - 1], it[J], N))
        out.push_back ({ it[I - 1], it[I], it[J - 1], it[J] });
  return out;
}
static std::vector<xo_cross> xo_check (const int E[2], const std::vector<int> &it,
                                       const std::vector<xo_pt> &N)
{
  std::vector<xo_cross> out;
  const int L = (int)it.size ();
  for (int I = 1; I <= L - 1; I++)
    if (xo_crossed (E[0], E[1], it[I - 1], it[I], N))
      out.push_back ({ E[0], E[1], it[I - 1], it[I] });
  return out;
}
static std::vector<xo_cross> xo_remove (const std::vector<xo_cross> &C,
                                        const int E[2])
{
  std::vector<xo_cross> out;
  for (const auto &c : C)
    if (!((c[0] == E[0] && c[1] == E[1]) || (c[1] == E[0] && c[0] == E[1])
          || (c[2] == E[0] && c[3] == E[1]) || (c[3] == E[0] && c[2] == E[1])))
      out.push_back (c);
  return out;
}
static bool xo_same (sisal_array_t a, const std::vector<xo_cross> &want)
{
  const int n = (int)want.size ();
  if ((int)a.size != n * 4) return false;
  // a non-empty cross list must be a genuine rank-3 n x 2 x 2 block; an empty
  // one packs to the empty seed, which has no inner shape to report
  if (n > 0
      && (a.rank != 3 || (int)a.dims[0] != n || (int)a.dims[1] != 2
          || (int)a.dims[2] != 2))
    return false;
  for (int i = 0; i < n; i++)
    for (int k = 0; k < 4; k++)
      if (((const int32_t *)a.data)[i * 4 + k] != want[i][k]) return false;
  return true;
}
static void test_crossovers_dv (void)
{
  printf ("\n=== Group: crossovers_dv (cross lists: list-packed vs "
          "COMPRESS-compacted) ===\n");

  // 8 nodes on a box plus node 9 at the centre, so an edge can END on another
  // edge's interior -- the closed-interval boundary the original's D3/D4 test
  // accepts and a strict "proper intersection" test would reject.
  const std::vector<xo_pt> N = { { 0, 0 },                        // index 0 unused
                                 { 0, 0 }, { 4, 0 }, { 8, 0 }, { 8, 4 },
                                 { 8, 8 }, { 4, 8 }, { 0, 8 }, { 0, 4 },
                                 { 4, 4 } };
  std::vector<int32_t> coords;
  for (size_t i = 1; i < N.size (); i++)
    { coords.push_back (N[i].x); coords.push_back (N[i].y); }

  struct Case { std::vector<int32_t> it; int32_t E[2]; const char *nm; };
  const std::vector<Case> cases = {
    { { 1, 5, 3, 7, 2, 6, 4, 8, 1 }, { 1, 5 }, "star tour, many crossings" },
    { { 1, 2, 3, 4, 5, 6, 7, 8, 1 }, { 1, 3 }, "convex octagon, none" },
    { { 1, 3, 2, 4, 6, 5, 7, 8, 1 }, { 2, 4 }, "mixed tour" },
    { { 1, 5, 9, 2, 7, 4, 1 },       { 9, 2 }, "edge ending on another edge" },
    { { 1, 2, 3 },                   { 1, 3 }, "too short to hold a pair" },
  };

  int n_all_bad = 0, n_chk_bad = 0, n_rem_bad = 0;
  int tot_all = 0, tot_removed = 0, n_empty = 0;
  char msg[160];
  for (const auto &c : cases)
    {
      const auto want_all = xo_find_all (c.it, N);
      const auto want_chk = xo_check (c.E, c.it, N);
      const auto want_rem = xo_remove (want_all, c.E);
      tot_all += (int)want_all.size ();
      tot_removed += (int)(want_all.size () - want_rem.size ());
      if (want_all.empty ()) n_empty++;

      sisal_array_t Co = sisal_array_alloc_empty (1, 6, coords.size ());
      memcpy (Co.data, coords.data (), coords.size () * sizeof (int32_t));
      sisal_array_t It = sisal_array_alloc_empty (1, 6, c.it.size ());
      memcpy (It.data, c.it.data (), c.it.size () * sizeof (int32_t));
      sisal_array_t Ex = sisal_array_alloc_empty (1, 6, 2);
      memcpy (Ex.data, c.E, sizeof c.E);

      auto r = func_MAIN (Co, It, Ex);

      bool ok = xo_same (r.all, want_all);
      if (!ok) n_all_bad++;
      snprintf (msg, sizeof msg, "%-32s Find_All_Crosses == reference (%zu)",
                c.nm, want_all.size ());
      check (msg, ok);

      ok = xo_same (r.chk, want_chk);
      if (!ok) n_chk_bad++;
      snprintf (msg, sizeof msg, "%-32s Check_Crossed == reference (%zu)", c.nm,
                want_chk.size ());
      check (msg, ok);

      ok = xo_same (r.rem, want_rem);
      if (!ok) n_rem_bad++;
      snprintf (msg, sizeof msg, "%-32s Remove_Edge == reference (%zu)", c.nm,
                want_rem.size ());
      check (msg, ok);

      if (Co.data) free (Co.data);
      if (It.data) free (It.data);
      if (Ex.data) free (Ex.data);
      if (r.all.data) free (r.all.data);
      if (r.chk.data) free (r.chk.data);
      if (r.rem.data) free (r.rem.data);
    }

  // Matching the reference proves nothing if the geometry never crosses, or if
  // Remove_Edge never had anything to drop.
  snprintf (msg, sizeof msg,
            "the tours actually cross (%d crossings, %d of them removed, "
            "%d empty cases)", tot_all, tot_removed, n_empty);
  check (msg, tot_all > 0 && tot_removed > 0 && n_empty > 0);
  check ("no mismatches anywhere",
         n_all_bad == 0 && n_chk_bad == 0 && n_rem_bad == 0);
}
#endif
#ifdef TEST_CYK_DV
// CYK recognition (test/unit/cyk.sis), on Hopcroft & Ullman's grammar
//     S -> A B | B C     A -> B A | a
//     B -> C C | b       C -> A B | a
// with S=1 A=2 B=3 C=4 and a=1 b=2.  The unit test hard-codes the DEGENERATE
// grammar NV=1, A -> a, A -> A A, which accepts every string -- an oracle that
// cannot fail.  Here the grammar is real, so acceptance actually depends on the
// split points the DP finds.
//
// The reference below is an independent CYK over the same productions, and both
// sides are compared on EVERY string over {a,b} of length 1..6 (126 of them) --
// accept bit AND the whole n x n table of "how many variables derive x[i..i+j-1]".
// The table is what makes a wrong split point visible: a recurrence that pairs
// V[k,i] with the wrong partner still gets the accept bit right on many strings.
static const int cyk_NV = 4;
static bool cyk_P1ref (int t, int A)
{
  return (t == 1 && A == 2) || (t == 1 && A == 4) || (t == 2 && A == 3);
}
static bool cyk_P2ref (int A, int B, int C)
{
  return (A == 1 && B == 2 && C == 3) || (A == 1 && B == 3 && C == 4)
         || (A == 2 && B == 3 && C == 2) || (A == 3 && B == 4 && C == 4)
         || (A == 4 && B == 2 && C == 3);
}
static bool cyk_ref (const std::vector<int> &x, std::vector<int> &cnt)
{
  const int n = (int)x.size ();
  std::vector<char> V ((size_t)(n + 1) * (n + 1) * (cyk_NV + 1), 0);
  auto at = [&] (int j, int i, int A) -> char & {
    return V[((size_t)j * (n + 1) + i) * (cyk_NV + 1) + A];
  };
  for (int i = 1; i <= n; i++)
    for (int A = 1; A <= cyk_NV; A++)
      at (1, i, A) = cyk_P1ref (x[i - 1], A);
  for (int j = 2; j <= n; j++)
    for (int i = 1; i <= n - j + 1; i++)
      for (int A = 1; A <= cyk_NV; A++)
        {
          bool any = false;
          for (int k = 1; k <= j - 1 && !any; k++)
            for (int B = 1; B <= cyk_NV && !any; B++)
              for (int C = 1; C <= cyk_NV && !any; C++)
                any = at (k, i, B) && at (j - k, i + k, C) && cyk_P2ref (A, B, C);
          at (j, i, A) = any;
        }
  cnt.assign ((size_t)n * n, 0);
  for (int j = 1; j <= n; j++)
    for (int i = 1; i <= n; i++)
      {
        int c = 0;
        if (i <= n - j + 1)
          for (int A = 1; A <= cyk_NV; A++)
            if (at (j, i, A)) c++;
        cnt[(size_t)(j - 1) * n + (i - 1)] = c;
      }
  return at (n, 1, 1);
}
static void test_cyk_dv (void)
{
  printf ("\n=== Group: cyk_dv (CYK parsing; rank-3 boolean array_dv DP table) "
          "===\n");

  int n_acc_bad = 0, n_cnt_bad = 0, n_shape_bad = 0, n_yes = 0, n_no = 0;
  for (int n = 1; n <= 6; n++)
    for (int code = 0; code < (1 << n); code++)
      {
        std::vector<int> x (n);
        for (int i = 0; i < n; i++)
          x[i] = ((code >> i) & 1) ? 2 : 1;          // bit set = 'b'

        std::vector<int> cnt;
        const bool acc = cyk_ref (x, cnt);
        (acc ? n_yes : n_no)++;

        sisal_array_t X = sisal_array_alloc_empty (1, 6, (uint64_t)n);
        for (int i = 0; i < n; i++)
          ((int32_t *)X.data)[i] = x[i];
        auto r = func_MAIN (X);

        if (r.res_0 != acc) n_acc_bad++;
        if (r.res_1.rank != 2 || (int)r.res_1.dims[0] != n
            || (int)r.res_1.dims[1] != n || (int)r.res_1.size != n * n)
          n_shape_bad++;
        else
          for (int t = 0; t < n * n; t++)
            if (((const int32_t *)r.res_1.data)[t] != cnt[t]) { n_cnt_bad++; break; }

        if (X.data) free (X.data);
        if (r.res_1.data) free (r.res_1.data);
      }

  // The sweep is only meaningful if the grammar SPLITS the strings; if every
  // one landed on the same side, matching the reference would prove nothing.
  char msg[160];
  snprintf (msg, sizeof msg,
            "the 126 strings split both ways (%d accepted, %d rejected)",
            n_yes, n_no);
  check (msg, n_yes > 0 && n_no > 0);
  check ("every accept bit matches the reference CYK", n_acc_bad == 0);
  check ("every count table is n x n", n_shape_bad == 0);
  check ("every count table matches cell for cell", n_cnt_bad == 0);

  // The textbook run, spelled out: baaba, with the V sets of Hopcroft & Ullman
  //   j=1  {B} {A,C} {A,C} {B} {A,C}          j=2  {S,A} {B} {S,C} {S,A}
  //   j=3  {}  {B}   {B}                      j=4  {}    {S,A,C}
  //   j=5  {S,A,C}   -> S is in it, so baaba is in the language.
  {
    const int32_t s[5] = { 2, 1, 1, 2, 1 };
    sisal_array_t X = sisal_array_alloc_empty (1, 6, 5);
    memcpy (X.data, s, sizeof s);
    auto r = func_MAIN (X);
    check ("baaba is in the language (S derives all five symbols)", r.res_0);

    static const int want[25] = { 1, 2, 2, 1, 2,
                                  2, 1, 2, 2, 0,
                                  0, 1, 1, 0, 0,
                                  0, 3, 0, 0, 0,
                                  3, 0, 0, 0, 0 };
    bool ok = r.res_1.size == 25;
    for (int t = 0; ok && t < 25; t++)
      ok = ((const int32_t *)r.res_1.data)[t] == want[t];
    check ("baaba's V table is the textbook one", ok);
    // the dead corner (i > n-j+1) must be carried as false, not read as garbage
    bool corner = r.res_1.size == 25;
    for (int j = 1; corner && j <= 5; j++)
      for (int i = 6 - j + 1; corner && i <= 5; i++)
        corner = ((const int32_t *)r.res_1.data)[(j - 1) * 5 + (i - 1)] == 0;
    check ("the unreachable corner of the table stays empty", corner);

    if (X.data) free (X.data);
    if (r.res_1.data) free (r.res_1.data);
  }

  // A single 'a' is derived by A and C but not by S, so a one-symbol string is
  // rejected while the table row is non-empty -- accept is not just "V is set".
  {
    const int32_t s[1] = { 1 };
    sisal_array_t X = sisal_array_alloc_empty (1, 6, 1);
    memcpy (X.data, s, sizeof s);
    auto r = func_MAIN (X);           // n = 1: the while loop is ZERO-TRIP
    check ("zero-trip (n=1): \"a\" rejected, but two variables derive it",
           !r.res_0 && r.res_1.size == 1
               && ((const int32_t *)r.res_1.data)[0] == 2);
    if (X.data) free (X.data);
    if (r.res_1.data) free (r.res_1.data);
  }
}
#endif
#ifdef TEST_MMULT2_DV
// mmult2 -- matrix multiply via transpose and dot-product rows
// (test/unit/mmult2.sis).  Third of the rank-2 cluster, and the only INTEGER
// one: the two Gauss ports check float solvers against tolerances, where a
// small systematic indexing error can hide inside a 1e-4 bound.  Here every
// element must match exactly, so a transposed or off-by-one read fails.
//
// DEVIATIONS, one cause: scattering over a rank-2 is unsupported in ANY form --
// `for Element in A at I,J` (2-D element scatter) is rejected just as `for Row
// in A at I` is.  Transpose became a cross forall; MatMult's outer loops became
// index loops.  The inner `for Aik in Row dot Bkj in Col` is over two rank-1s
// and is kept as written: rank-1 scatter is fine.
static void test_mmult2_dv (void)
{
  printf ("\n=== Group: mmult2_dv (integer matrix multiply, exact) ===\n");
  for (int N = 2; N <= 6; N++)
    {
      struct FUNC_MAIN_mm_results r = func_MAIN (N);
      std::vector<long> b ((size_t)(N * N));
      for (int i = 1; i <= N; i++)
        for (int j = 1; j <= N; j++) b[(i - 1) * N + (j - 1)] = i + (j - 1) * 2;

      char msg[190];
      snprintf (msg, sizeof msg, "N=%d  A and B are rank 2, %dx%d", N, N, N);
      check (msg, r.res_0.rank == 2 && (int)r.res_0.dims[0] == N
                      && (int)r.res_0.dims[1] == N && r.res_1.rank == 2
                      && (int)r.res_2.dims[0] == N);

      bool ab = ((int)r.res_0.size == N * N && (int)r.res_1.size == N * N);
      for (int i = 0; ab && i < N * N; i++)
        ab = ab && ((const int32_t *)r.res_0.data)[i] == b[i]
             && ((const int32_t *)r.res_1.data)[i] == b[i];
      snprintf (msg, sizeof msg, "N=%d  A,B match i + (j-1)*2 exactly", N);
      check (msg, ab);

      bool cb = ((int)r.res_2.size == N * N);
      for (int i = 0; cb && i < N; i++)
        for (int k = 0; cb && k < N; k++)
          {
            long acc = 0;
            for (int j = 0; j < N; j++) acc += b[i * N + j] * b[j * N + k];
            cb = cb && ((const int32_t *)r.res_2.data)[i * N + k] == acc;
          }
      snprintf (msg, sizeof msg, "N=%d  C == A*B, every element exact", N);
      check (msg, cb);

      // `A := B` in Main, so res_0 and res_1 ALIAS THE SAME BUFFER -- freeing
      // both is a double free (exit 133).  Same trap as life1_dv, where a
      // zero-iteration result aliased its input.
      if (r.res_0.data) free (r.res_0.data);
      if (r.res_1.data && r.res_1.data != r.res_0.data) free (r.res_1.data);
      if (r.res_2.data && r.res_2.data != r.res_0.data) free (r.res_2.data);
    }
}
#endif

